<script setup>
import {ref,computed} from 'vue';import {Head,Link,useForm,usePage} from '@inertiajs/vue3';import Badge from '../Components/Badge.vue';import Errors from '../Components/Errors.vue';import {statuses,date} from '../lib/labels';import {MapPin,Phone,Clock3} from 'lucide-vue-next';
const props=defineProps({incident:Object,technicians:Array,canManage:Boolean,canConfirm:Boolean,nearbyPoints:Array});const u=usePage().props.auth.user;const status=useForm({status:'',comment:'',priority:props.incident.priority,priority_reason:props.incident.priority_reason||'',blocker:props.incident.blocker||'',duplicate_of:'',water_point_id:props.incident.water_point_id||''});const plan=useForm({technician_id:'',scheduled_at:'',estimated_cost:null});const confirmation=useForm({working:true,comment:''});const report=useForm({acceptance:'acceptee',diagnosis:'',work_done:'',performed_at:'',estimated_cost:null,actual_cost:null,blocker:'',recommendation:'',parts:[],repaired:false,photo:null});const editing=ref(null);const options=computed(()=>({signale:['verification','non_retenu','doublon'],verification:['non_retenu','doublon'],planifie:['verification'],repare:['verification'],confirme:['verification'],non_retenu:['verification'],doublon:['verification']})[props.incident.status]||[]);function edit(v){editing.value=v.id;report.defaults({acceptance:v.acceptance==='en_attente'?'acceptee':v.acceptance,diagnosis:v.diagnosis||'',work_done:v.work_done||'',performed_at:v.performed_at||'',estimated_cost:v.estimated_cost,actual_cost:v.actual_cost,blocker:v.blocker||'',recommendation:v.recommendation||'',parts:v.parts.map(p=>({name:p.name,quantity:p.quantity,state:p.state})),repaired:false,photo:null});report.reset();}function saveReport(){report.post('/interventions/'+editing.value,{forceFormData:true,onSuccess:()=>editing.value=null});}
</script><template><Head :title="incident.reference"/><Link class="text-link" href="/incidents">← Tous les signalements</Link><div class="page-heading heading-row mt"><div><span class="eyebrow">{{incident.reference}}</span><h1>{{incident.water_point?.name||'Point non répertorié'}}</h1><p>{{incident.locality?.name}} · Signalé le {{date(incident.created_at)}}</p></div><Badge :value="incident.status"/></div><div class="grid dashboard-columns"><section class="form-stack"><article class="card"><div class="card-heading"><h3>Le constat</h3><span class="badge">Priorité {{incident.priority}}</span></div><p>{{incident.description}}</p><p class="location mt"><MapPin :size="16"/>{{incident.landmark||incident.locality?.name}}</p><p class="location"><Phone :size="16"/>{{incident.reporter_name}} · {{incident.phone}}</p><p v-if="incident.blocker" class="notice error">Blocage : {{incident.blocker}}</p><p v-if="incident.priority_reason" class="muted">Priorité motivée : {{incident.priority_reason}}</p><div class="photos"><a v-for="a in incident.attachments" :key="a.id" :href="'/photos/'+a.id" target="_blank" rel="noopener"><img :src="'/photos/'+a.id" alt="Photo du signalement" loading="lazy"></a></div></article>
<form v-if="canManage" class="card form-stack" @submit.prevent="status.post('/incidents/'+incident.id+'/statut')"><h3>Vérification et suivi</h3><Errors :errors="status.errors"/><label>Point d’eau associé<select v-model="status.water_point_id"><option value="">Point non répertorié</option><option v-for="p in nearbyPoints" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Évolution<select v-model="status.status"><option value="">Ajouter une note sans changer le statut</option><option v-for="s in options" :key="s" :value="s">{{statuses[s]}}</option></select></label><label v-if="status.status==='doublon'">Identifiant de l’incident principal<input v-model="status.duplicate_of" type="number" min="1" required></label><div class="grid two"><label>Priorité<select v-model="status.priority"><option value="normale">Normale</option><option value="haute">Haute</option><option value="urgente">Urgente</option></select></label><label>Motif de priorité<input v-model="status.priority_reason" required></label></div><label>Blocage éventuel<input v-model="status.blocker" placeholder="Attente de pièce, financement..."></label><label>Commentaire<textarea v-model="status.comment" required minlength="5" rows="3"></textarea></label><button class="btn btn-primary" :disabled="status.processing">Enregistrer le suivi</button></form>
<form v-if="canManage&&['verification','planifie'].includes(incident.status)" class="card form-stack" @submit.prevent="plan.post('/incidents/'+incident.id+'/interventions')"><h3>Planifier une intervention</h3><Errors :errors="plan.errors"/><label>Technicien<select v-model="plan.technician_id" required><option value="" disabled>Choisir un technicien</option><option v-for="t in technicians" :key="t.id" :value="t.id">{{t.name}}</option></select></label><div class="grid two"><label>Date prévue<input v-model="plan.scheduled_at" type="date" required></label><label>Coût estimé · FCFA<input v-model="plan.estimated_cost" type="number" min="0"></label></div><button class="btn btn-primary" :disabled="plan.processing">Affecter et planifier</button></form>
<article class="card" v-for="v in incident.interventions" :key="v.id"><div class="card-heading"><h3>Intervention #{{v.id}}</h3><span class="badge">{{v.acceptance}}</span></div><p><strong>{{v.technician?.name}}</strong> · Prévue le {{date(v.scheduled_at)}}</p><dl><div><dt>Diagnostic</dt><dd>{{v.diagnosis||'À renseigner'}}</dd></div><div><dt>Travaux</dt><dd>{{v.work_done||'À renseigner'}}</dd></div><div><dt>Coût estimé / réel</dt><dd>{{v.estimated_cost??'—'}} / {{v.actual_cost??'—'}} FCFA</dd></div></dl><p v-if="v.blocker" class="notice error">{{v.blocker}}</p><p v-if="v.recommendation">Conseil : {{v.recommendation}}</p><ul class="parts"><li v-for="p in v.parts" :key="p.id">{{p.quantity}} × {{p.name}} · {{p.state}}</li></ul><button v-if="incident.status==='planifie'&&(canManage||v.technician_id===u.id)" class="btn btn-soft mt" @click="edit(v)">Renseigner le compte rendu</button></article>
<form v-if="editing" class="card form-stack" @submit.prevent="saveReport"><h3>Compte rendu technique</h3><Errors :errors="report.errors"/><label>Acceptation<select v-model="report.acceptance"><option value="acceptee">Acceptée</option><option value="indisponible">Indisponible</option></select></label><label>Diagnostic<textarea v-model="report.diagnosis" rows="2"></textarea></label><label>Travaux effectués<textarea v-model="report.work_done" rows="3"></textarea></label><div class="grid two"><label>Date réelle<input type="date" v-model="report.performed_at"></label><label>Coût réel · FCFA<input type="number" min="0" v-model="report.actual_cost"></label></div><label>Blocage<input v-model="report.blocker"></label><label>Recommandation<input v-model="report.recommendation"></label><label>Photo facultative<input type="file" accept="image/jpeg,image/png,image/webp" @change="report.photo=$event.target.files[0]"></label><h4>Pièces</h4><div v-for="(p,k) in report.parts" :key="k" class="part-row"><input v-model="p.name" placeholder="Nom de la pièce" required><input type="number" v-model="p.quantity" min="1" required><select v-model="p.state"><option value="necessaire">Nécessaire</option><option value="utilisee">Utilisée</option></select><button type="button" @click="report.parts.splice(k,1)" aria-label="Retirer la pièce">×</button></div><button type="button" class="btn btn-soft small" @click="report.parts.push({name:'',quantity:1,state:'necessaire'})">+ Ajouter une pièce</button><label class="checkbox"><input type="checkbox" v-model="report.repaired">La réparation est terminée ; demander confirmation du retour de l’eau.</label><button class="btn btn-primary" :disabled="report.processing">Enregistrer le compte rendu</button></form>
<form v-if="canConfirm&&incident.status==='repare'" class="card form-stack" @submit.prevent="confirmation.post('/incidents/'+incident.id+'/confirmer')"><h3>Confirmer le retour de l’eau</h3><Errors :errors="confirmation.errors"/><label>Résultat<select v-model="confirmation.working"><option :value="true">L’eau est de nouveau disponible</option><option :value="false">Le problème persiste</option></select></label><label>Votre constat<textarea v-model="confirmation.comment" required minlength="5" rows="3"></textarea></label><button class="btn btn-primary" :disabled="confirmation.processing">Enregistrer la confirmation</button></form></section>
<aside class="card timeline-card"><h3>Historique du signalement</h3><ol class="timeline"><li v-for="h in incident.histories" :key="h.id"><strong>{{statuses[h.to_status]}}</strong><p>{{h.comment}}</p><small>{{h.actor?.name||'Déclarant ou système'}} · {{date(h.created_at)}}</small></li></ol></aside></div></template>
